"use client";
import { useEffect,useState } from "react"; import Link from "next/link"; import { Eye,EyeOff,Store } from "lucide-react"; import { api,ApiError } from "@/lib/api-client";
type Visibility="PUBLIC"|"PRIVATE"|"DISPLAY"; type Result={profile:{visibility:Visibility};vendorProfile:{storeName:string;storeSlug:string}};
export default function StoreVisibilityPage(){const[data,setData]=useState<Result|null>(null);const[value,setValue]=useState<Visibility>("PUBLIC");const[busy,setBusy]=useState(false);const[message,setMessage]=useState("");const[error,setError]=useState("");useEffect(()=>{void api.get<Result>("/api/store-visibility/me").then(r=>{setData(r);setValue(r.profile.visibility)}).catch(e=>setError(e instanceof ApiError?e.message:"Unable to load store visibility"))},[]);async function save(){setBusy(true);setMessage("");setError("");try{const r=await api.patch<Result>("/api/store-visibility/me",{visibility:value});setData(r);setMessage("Store visibility updated.")}catch(e){setError(e instanceof ApiError?e.message:"Unable to update store visibility")}finally{setBusy(false)}}return <div className="shell max-w-3xl py-8"><Link href="/vendor/dashboard" className="text-sm font-semibold text-graphite-500">← Back to dashboard</Link><div className="mt-5 flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-card bg-cloud-100 dark:bg-graphite-800"><Store className="h-5 w-5"/></span><div><h1 className="text-2xl font-bold">Store visibility</h1><p className="text-sm text-graphite-500">{data?.vendorProfile.storeName??"Your store"}</p></div></div><div className="mt-6 grid gap-3">{(["PUBLIC","DISPLAY","PRIVATE"] as Visibility[]).map(option=><label key={option} className={`cursor-pointer rounded-card border p-5 ${value===option?"border-ember-600 bg-ember-50 dark:bg-ember-950/20":"border-graphite-200 dark:border-graphite-700"}`}><input type="radio" name="visibility" checked={value===option} onChange={()=>setValue(option)} className="mr-3"/><span className="font-semibold">{option==="PUBLIC"?"Public Store":option==="DISPLAY"?"Display Store":"Private Store"}</span><span className="mt-1 block pl-6 text-sm text-graphite-500">{option==="PUBLIC"?"Discoverable in TTFL Store search and public store directories.":option==="DISPLAY"?"Public brand/service storefront designed for services, advertising, and business presence.":"Hidden from public store discovery."}</span></label>)}</div>{message&&<p className="mt-4 text-sm font-semibold text-verified-600">{message}</p>}{error&&<p className="mt-4 text-sm font-semibold text-ember-600">{error}</p>}<button onClick={()=>void save()} disabled={busy} className="mt-5 rounded-card bg-ember-600 px-5 py-3 text-sm font-semibold text-white disabled:opacity-60">{busy?"Saving…":"Save visibility"}</button><div className="mt-8 rounded-card border border-graphite-200 p-5 dark:border-graphite-700"><div className="flex items-start gap-3"><Eye className="mt-0.5 h-5 w-5 text-graphite-500"/><div><p className="font-semibold">Public</p><p className="text-sm text-graphite-500">Customers can discover your store normally.</p><EyeOff className="mt-4 h-5 w-5 text-graphite-500"/><p className="mt-1 font-semibold">Private</p><p className="text-sm text-graphite-500">Your store is not listed publicly. Direct access can still be supported.</p></div></div></div></div>}
